-- ----------------------------------------------------------------------------
-- user_permissions (사용자별 추가 부여/제외 예시 — perm_key 로 조회해 seed_core 순서에 비의존)
-- ----------------------------------------------------------------------------
INSERT INTO `user_permissions` (`id`,`user_id`,`permission_id`,`is_grant`)
SELECT v.id, v.user_id, p.id, v.is_grant FROM (VALUES
  ROW(1, 4, 'report.view', 1),
  ROW(2, 3, 'staff.view', 1),
  ROW(3, 5, 'cost.manage', 0)
) AS v(id, user_id, perm_key, is_grant)
JOIN `permissions` p ON p.perm_key = v.perm_key;

