-- 실제원가 캐시를 costs(actual) 합계와 일치시킴 (앱은 CostsController 가 저장 시 자동 갱신)
UPDATE projects p SET actual_cost = COALESCE((SELECT SUM(amount) FROM costs c WHERE c.project_id=p.id AND c.type='actual'),0);
